/// VM replay implementations for security bindings.
#[inline]
fn destack_security_sandbox_enter_vm_replay(
    runtime: &RuntimeCallContext,
    context: &mut vm::ExternalCallContext<'_>,
    name: vm::StringHandle,
) -> RuntimeResult<vm::Value> {
    let result = runtime
        .replay()
        .run_binding_with_context_and_payload_policy(
            SECURITY_SANDBOX_ENTER,
            runtime.replay_payload_for(SECURITY_SANDBOX_ENTER)?,
            context,
            |context| platform_runtime_vm::destack_security_sandbox_enter(runtime, context, name),
            |context, result| {
                let _ = &context;
                if let Ok(value) = result {
                    let result_value: resource::SandboxHandle = value.clone();
                    let result_recorded = result_value;
                    let payload = SecuritySandboxEnterReplay {
                        result: Ok(result_recorded),
                    };
                    return Ok(Some(payload));
                }

                if let Err(error) = result {
                    let payload = {
                        let result = Err(PlatformError::from(error.as_ref()));
                        SecuritySandboxEnterReplay { result }
                    };
                    return Ok(Some(payload));
                }

                Ok(None)
            },
            |context, payload| {
                let _ = &context;
                // replay result
                match payload.result {
                    Ok(value) => {
                        let vm_result = value;
                        Ok(vm_result)
                    }
                    Err(error) => Err(RuntimeError::from(error).boxed()),
                }
            },
        );
    let result = encode_destack_security_sandbox_enter_result(context, result)?;
    Ok(result)
}

#[inline]
fn destack_security_sandbox_exit_vm_replay(
    runtime: &RuntimeCallContext,
    context: &mut vm::ExternalCallContext<'_>,
    handle: resource::SandboxHandle,
) -> RuntimeResult<vm::Value> {
    let result = runtime
        .replay()
        .run_binding_with_context_and_payload_policy(
            SECURITY_SANDBOX_EXIT,
            runtime.replay_payload_for(SECURITY_SANDBOX_EXIT)?,
            context,
            |context| platform_runtime_vm::destack_security_sandbox_exit(runtime, context, handle),
            |context, result| {
                let _ = &context;
                if let Ok(()) = result {
                    let result_recorded = ();
                    let payload = SecuritySandboxExitReplay {
                        result: Ok(result_recorded),
                    };
                    return Ok(Some(payload));
                }

                if let Err(error) = result {
                    let payload = {
                        let result = Err(PlatformError::from(error.as_ref()));
                        SecuritySandboxExitReplay { result }
                    };
                    return Ok(Some(payload));
                }

                Ok(None)
            },
            |context, payload| {
                let _ = &context;
                // replay result
                match payload.result {
                    Ok(()) => Ok(()),
                    Err(error) => Err(RuntimeError::from(error).boxed()),
                }
            },
        );
    let result = encode_destack_security_sandbox_exit_result(context, result)?;
    Ok(result)
}

/// Register VM bindings for security.
pub fn register_security_vm_bindings(registry: &mut BindingRegistry, isolate: &mut Isolate) {
    {
        binding!(
            registry,
            isolate,
            SECURITY_CAPABILITY_HAS,
            move |context, args| {
                with_runtime_call_context(|runtime| {
                    // decode args
                    let (capability,) = decode_destack_security_capability_has_args(context, args)?;

                    // execute binding
                    let result = {
                        runtime.check_policy(SECURITY_CAPABILITY_HAS)?;
                        platform_runtime_vm::destack_security_capability_has(
                            runtime, context, capability,
                        )
                    };
                    encode_destack_security_capability_has_result(context, result)
                })
                .map_err(Into::into)
            }
        );
    }
    {
        binding!(
            registry,
            isolate,
            SECURITY_CAPABILITY_LIST,
            move |context, _args| {
                with_runtime_call_context(|runtime| {
                    // execute binding
                    let result = {
                        runtime.check_policy(SECURITY_CAPABILITY_LIST)?;
                        platform_runtime_vm::destack_security_capability_list(runtime, context)
                    };
                    encode_destack_security_capability_list_result(context, result)
                })
                .map_err(Into::into)
            }
        );
    }
    {
        binding!(
            registry,
            isolate,
            SECURITY_ENFORCE_SANDBOX_INSTALL_FILTER,
            move |context, args| {
                with_runtime_call_context(|runtime| {
                    // decode args
                    let (handle, filter) =
                        decode_destack_security_enforce_sandbox_install_filter_args(context, args)?;

                    // execute binding
                    let result = {
                        let world = runtime
                            .check_and_resolve_world(SECURITY_ENFORCE_SANDBOX_INSTALL_FILTER)?;
                        match world {
                            RuntimeWorld::Host => {
                                platform_vm::destack_security_sandbox_install_filter(
                                    runtime, context, handle, filter,
                                )
                            }
                            RuntimeWorld::Simulated => {
                                platform_simulated_vm::destack_security_sandbox_install_filter(
                                    runtime, context, handle, filter,
                                )
                            }
                        }
                    };
                    encode_destack_security_enforce_sandbox_install_filter_result(context, result)
                })
                .map_err(Into::into)
            }
        );
    }
    {
        binding!(
            registry,
            isolate,
            SECURITY_ENFORCE_SANDBOX_SEAL,
            move |context, args| {
                with_runtime_call_context(|runtime| {
                    // decode args
                    let (handle,) =
                        decode_destack_security_enforce_sandbox_seal_args(context, args)?;

                    // execute binding
                    let result = {
                        runtime.check_policy(SECURITY_ENFORCE_SANDBOX_SEAL)?;
                        platform_runtime_vm::destack_security_sandbox_seal(runtime, context, handle)
                    };
                    encode_destack_security_enforce_sandbox_seal_result(context, result)
                })
                .map_err(Into::into)
            }
        );
    }
    {
        binding!(
            registry,
            isolate,
            SECURITY_ENFORCE_SANDBOX_SET_CAPABILITIES,
            move |context, args| {
                with_runtime_call_context(|runtime| {
                    // decode args
                    let (handle, capabilities) =
                        decode_destack_security_enforce_sandbox_set_capabilities_args(
                            context, args,
                        )?;

                    // execute binding
                    let result = {
                        runtime.check_policy(SECURITY_ENFORCE_SANDBOX_SET_CAPABILITIES)?;
                        platform_runtime_vm::destack_security_sandbox_set_capabilities(
                            runtime,
                            context,
                            handle,
                            capabilities,
                        )
                    };
                    encode_destack_security_enforce_sandbox_set_capabilities_result(context, result)
                })
                .map_err(Into::into)
            }
        );
    }
    {
        binding!(
            registry,
            isolate,
            SECURITY_POLICY_GET,
            move |context, args| {
                with_runtime_call_context(|runtime| {
                    // decode args
                    let (scope,) = decode_destack_security_policy_get_args(context, args)?;

                    // execute binding
                    let result = {
                        runtime.check_policy(SECURITY_POLICY_GET)?;
                        platform_runtime_vm::destack_security_policy_get(runtime, context, scope)
                    };
                    encode_destack_security_policy_get_result(context, result)
                })
                .map_err(Into::into)
            }
        );
    }
    {
        binding!(
            registry,
            isolate,
            SECURITY_POLICY_GET_RULES,
            move |context, args| {
                with_runtime_call_context(|runtime| {
                    // decode args
                    let (scope,) = decode_destack_security_policy_get_rules_args(context, args)?;

                    // execute binding
                    let result = {
                        runtime.check_policy(SECURITY_POLICY_GET_RULES)?;
                        platform_runtime_vm::destack_security_policy_get_rules(
                            runtime, context, scope,
                        )
                    };
                    encode_destack_security_policy_get_rules_result(context, result)
                })
                .map_err(Into::into)
            }
        );
    }
    {
        binding!(
            registry,
            isolate,
            SECURITY_POLICY_SET,
            move |context, args| {
                with_runtime_call_context(|runtime| {
                    // decode args
                    let (scope, capabilities) =
                        decode_destack_security_policy_set_args(context, args)?;

                    // execute binding
                    let result = {
                        runtime.check_policy(SECURITY_POLICY_SET)?;
                        platform_runtime_vm::destack_security_policy_set(
                            runtime,
                            context,
                            scope,
                            capabilities,
                        )
                    };
                    encode_destack_security_policy_set_result(context, result)
                })
                .map_err(Into::into)
            }
        );
    }
    {
        binding!(
            registry,
            isolate,
            SECURITY_POLICY_SET_RULES,
            move |context, args| {
                with_runtime_call_context(|runtime| {
                    // decode args
                    let (scope, rules) =
                        decode_destack_security_policy_set_rules_args(context, args)?;

                    // execute binding
                    let result = {
                        runtime.check_policy(SECURITY_POLICY_SET_RULES)?;
                        platform_runtime_vm::destack_security_policy_set_rules(
                            runtime, context, scope, rules,
                        )
                    };
                    encode_destack_security_policy_set_rules_result(context, result)
                })
                .map_err(Into::into)
            }
        );
    }
    {
        binding!(
            registry,
            isolate,
            SECURITY_SANDBOX_ENTER,
            move |context, args| {
                with_runtime_call_context(|runtime| {
                    // decode args
                    let (name,) = decode_destack_security_sandbox_enter_args(context, args)?;

                    // execute binding
                    runtime.check_policy(SECURITY_SANDBOX_ENTER)?;
                    destack_security_sandbox_enter_vm_replay(runtime, context, name)
                })
                .map_err(Into::into)
            }
        );
    }
    {
        binding!(
            registry,
            isolate,
            SECURITY_SANDBOX_EXIT,
            move |context, args| {
                with_runtime_call_context(|runtime| {
                    // decode args
                    let (handle,) = decode_destack_security_sandbox_exit_args(context, args)?;

                    // execute binding
                    runtime.check_policy(SECURITY_SANDBOX_EXIT)?;
                    destack_security_sandbox_exit_vm_replay(runtime, context, handle)
                })
                .map_err(Into::into)
            }
        );
    }
}

/// Install VM bindings for security.
pub fn install_security_vm_bindings(registry: &mut BindingRegistry, isolate: &mut Isolate) {
    register_security_vm_bindings(registry, isolate);
}

vm_binding_set!(pub SECURITY_VM_BINDINGS, "security", install_security_vm_bindings);
